WITH parsed AS (SELECT id, service, level, status_code, context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, context['region'] AS region, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs) SELECT id, duration_text, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level), 4) AS status_code_share, LAG(retry_count, 1) OVER w_recent AS prev_retry_count, LAG(status_code, 1, 0) OVER (PARTITION BY level ORDER BY retry_count, id) AS prev_status_code FROM parsed WINDOW w_recent AS (ORDER BY status_code, id)
